using CheckoutPricing.Application;
using CheckoutPricing.Domain;

namespace CheckoutPricing.UnitTest.Features.Discount;

public class DiscountAcceptanceTests
{
    private readonly CalculateLoyaltyDiscount _calculateLoyaltyDiscount = new();

    // Bronze customer is charged the basket less the Bronze reduction
    [Fact]
    public void S1_BronzeCustomerIsChargedTheBasketLessTheBronzeReduction()
    {
        var quote = _calculateLoyaltyDiscount.Handle(new CalculateLoyaltyDiscountQuery(10000, LoyaltyTier.Bronze));

        Assert.Equal(9500, quote.TotalCents);
    }

    // Silver customer is charged the basket less the Silver reduction
    [Fact]
    public void S2_SilverCustomerIsChargedTheBasketLessTheSilverReduction()
    {
        var quote = _calculateLoyaltyDiscount.Handle(new CalculateLoyaltyDiscountQuery(10000, LoyaltyTier.Silver));

        Assert.Equal(9000, quote.TotalCents);
    }

    // Gold customer is charged the basket less the Gold reduction
    [Fact]
    public void S3_GoldCustomerIsChargedTheBasketLessTheGoldReduction()
    {
        var quote = _calculateLoyaltyDiscount.Handle(new CalculateLoyaltyDiscountQuery(10000, LoyaltyTier.Gold));

        Assert.Equal(8500, quote.TotalCents);
    }

    // Bronze customer with a tiny basket is charged the full subtotal
    [Fact]
    public void S4_BronzeCustomerWithATinyBasketIsChargedTheFullSubtotal()
    {
        var quote = _calculateLoyaltyDiscount.Handle(new CalculateLoyaltyDiscountQuery(7, LoyaltyTier.Bronze));

        Assert.Equal(7, quote.TotalCents);
    }
}

